--
-- Table structure for table `class_attendance_records`
--

DROP TABLE IF EXISTS `class_attendance_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `class_attendance_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `session_id` int NOT NULL,
  `class_id` int NOT NULL,
  `student_id` int NOT NULL,
  `status` enum('present','excused_absence','unexcused_absence','late') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'present',
  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recorded_by_user_id` int DEFAULT NULL,
  `recorded_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_session_student` (`session_id`,`student_id`),
  KEY `idx_car_session` (`session_id`),
  KEY `idx_car_class` (`class_id`),
  KEY `idx_car_student` (`student_id`),
  KEY `idx_car_status` (`status`),
  CONSTRAINT `fk_car_class` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_car_session` FOREIGN KEY (`session_id`) REFERENCES `class_attendance_sessions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_car_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13288 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

