--
-- Table structure for table `class_attendance_sessions`
--

DROP TABLE IF EXISTS `class_attendance_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `class_attendance_sessions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `class_id` int NOT NULL,
  `session_date` date NOT NULL,
  `session_time` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '07:00',
  `shift_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'Đầu giờ sáng',
  `total_students` int DEFAULT '0',
  `present_count` int DEFAULT '0',
  `excused_count` int DEFAULT '0',
  `unexcused_count` int DEFAULT '0',
  `late_count` int DEFAULT '0',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'completed',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `recorded_by_user_id` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_class_session_date` (`class_id`,`session_date`),
  KEY `idx_date` (`session_date`),
  KEY `idx_class` (`class_id`),
  CONSTRAINT `fk_cas_class` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=382 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

