INSERT INTO `daily_regimes` VALUES (1,1,'05:15','05:30','Báo thức','Chuông báo thức toàn KTX, học sinh thức dậy chuẩn bị','Ban Quản sinh',1),(2,2,'05:30','06:00','Thể dục sáng','Tập thể dục sân KTX nâng cao thể lực','Ban Tự quản KTX',1),(3,3,'06:00','06:30','Gấp chăn màn, chỉnh trang nội vụ','Vệ sinh phòng, gấp chăn vuông vắn, xếp đồ dùng','Trưởng phòng KTX',1),(4,4,'06:30','07:15','Ăn sáng','Ăn sáng tại nhà ăn trường THPT Chuyên Hùng Vương','Ban Quản sinh',1),(5,5,'07:15','07:30','Niêm phong KTX','Khóa các phòng KTX, niêm phong cửa tầng','Ban Quản sinh & Bảo vệ',1),(6,6,'07:30','11:30','Học chính khóa tại Tòa nhà A','Học tập các môn chuyên và đại trà tại giảng đường','GVCN & Trực ban',1),(7,7,'11:45','13:30','Ăn trưa và nghỉ trưa','Nghỉ trưa giữ yên tĩnh tại các phòng nội trú','Trưởng tầng & Quản sinh',1),(8,8,'16:30','17:45','Thể thao chiều','Hoạt động thể chất bóng rổ, cầu lông, bóng bàn','Đoàn Thanh niên',1),(9,9,'18:00','18:15','Chốt cổng trường KTX','Kiểm soát học sinh nội trú trở về KTX','Bảo vệ & Quản sinh',1),(10,10,'19:30','21:45','Tự học tối','Tự học tại phòng học hoặc phòng tự học KTX','Trưởng tầng & Trưởng phòng',1),(11,11,'22:00','22:30','Điểm danh tối & Tắt đèn','Điểm danh quân số, tắt đèn ngủ lúc 22h30','Trưởng phòng & Quản sinh',1);
