--
-- Table structure for table `violation_records`
--

DROP TABLE IF EXISTS `violation_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `violation_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `student_id` int NOT NULL,
  `class_id` int NOT NULL,
  `rule_id` int NOT NULL,
  `period_id` int NOT NULL,
  `violation_date` date NOT NULL,
  `violation_time` time DEFAULT NULL,
  `location` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `points_deducted` int NOT NULL,
  `reported_by_user_id` int NOT NULL,
  `evidence_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'approved',
  `approved_by_user_id` int DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `class_id` (`class_id`),
  KEY `rule_id` (`rule_id`),
  KEY `period_id` (`period_id`),
  KEY `idx_violation_student` (`student_id`),
  KEY `idx_violation_date` (`violation_date`),
  KEY `idx_violation_status` (`status`),
  CONSTRAINT `violation_records_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `violation_records_ibfk_2` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`),
  CONSTRAINT `violation_records_ibfk_3` FOREIGN KEY (`rule_id`) REFERENCES `kpi_rules` (`id`),
  CONSTRAINT `violation_records_ibfk_4` FOREIGN KEY (`period_id`) REFERENCES `kpi_assessment_periods` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

